"""Review selected received inventory files before showing their quantities."""
HTML='''<section class="card files-section" id="selected-inventory-panel"><h2>USAR INVENTARIOS RECIBIDOS EN STOCK Y PROPUESTAS</h2><p id="selected-inventory-company"></p><p>Primero recibe tu Excel o CSV como Inventario. Después, en Expedientes recibidos, marca solo los archivos de inventario de esta empresa y fecha de corte. Puedes seleccionar varias partes, sin repetir SKU.</p><button id="selected-inventory-preview" type="button">Ver cambios de los inventarios marcados</button><div id="selected-inventory-review" class="files-step" hidden><h3>COMPARACIÓN ANTES DE UTILIZAR</h3><p id="selected-inventory-summary"></p><div id="selected-inventory-rows" class="scroll"></div><p>Esta selección sustituye la selección de inventarios recibidos anterior. Incluye todas las partes que quieras utilizar. Para SKU no incluidos se conservan las referencias originales del caso ficticio, si existen; no se completa lo desconocido con cero. No se activan los parámetros de stock del archivo ni se reutiliza automáticamente su planificación anterior.</p></div><div class="fields"><label>Responsable<input id="selected-inventory-actor" maxlength="500"></label><label>Motivo<input id="selected-inventory-reason" maxlength="500"></label></div><label><input id="selected-inventory-ack" type="checkbox" style="display:inline;width:auto"> He revisado las cantidades y su fecha. Se usarán como referencias al corte; no acreditan el stock actual ni autorizan compras.</label><div class="files-actions"><button id="selected-inventory-commit" type="button" class="primary" disabled>Usar estas existencias en Stock y propuestas</button><button id="selected-inventory-clear" type="button" disabled>Retirar la selección de inventario</button></div><p id="selected-inventory-current"></p><p id="selected-inventory-notice" class="files-notice" role="status"></p></section>'''
JS=r'''
let selectedInventoryTicket=null,selectedInventorySequence=0,selectedInventoryBusy=false;
function invalidateSelectedInventory(){selectedInventorySequence++;selectedInventoryTicket=null;$('selected-inventory-ack').checked=false;$('selected-inventory-review').hidden=true;$('selected-inventory-commit').disabled=true}
function renderSelectedInventory(){invalidateSelectedInventory();$('selected-inventory-company').textContent='Empresa activa: '+(state.info.company.legal_name||state.info.company.company_id)+' · corte '+stockDate(state.info.as_of_date);const s=state.selected_inventory;$('selected-inventory-current').textContent=s?s.message+(s.status==='SELECTED'?' '+s.article_count+' artículos · revisión '+s.revision+'.':''):'Sin inventarios recibidos seleccionados; se conservan las referencias del caso ficticio.';$('selected-inventory-clear').disabled=!s||s.status==='CLEARED';$('selected-inventory-ack').checked=false}
$('selected-inventory-ack').onchange=()=>{$('selected-inventory-commit').disabled=!selectedInventoryTicket||!$('selected-inventory-ack').checked};
$('selected-inventory-preview').onclick=async()=>{invalidateSelectedInventory();const sequence=selectedInventorySequence,dataset=$('dataset').value,batch_ids=[...$('received-batches').querySelectorAll('input:checked')].map(x=>x.value);selectedInventoryBusy=true;$('selected-inventory-preview').disabled=true;$('selected-inventory-notice').textContent='Comprobando empresa, corte, SKU, unidades y cantidades…';try{const r=await api('/api/inventory/preview',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,context_fingerprint:state.documentary_context.fingerprint,batch_ids})});if(sequence!==selectedInventorySequence||dataset!==$('dataset').value)return;selectedInventoryTicket=r.ticket;$('selected-inventory-review').hidden=false;$('selected-inventory-summary').textContent=r.files.join(' · ')+' · '+r.article_count+' artículos · '+r.unknown_reservations+' sin reservas documentadas · '+r.error_count+' errores. '+(r.replaces_previous_selection?'Sustituye la selección anterior; '+r.reverted_articles+' SKU dejan de usarla. ':'')+'Mostrando '+r.sample_count+' de '+r.article_count+' filas.';receptionTable('selected-inventory-rows',['SKU / unidad','Físico anterior','Físico propuesto','Reservado anterior','Reservado propuesto','Disponible anterior','Disponible propuesto','Archivo / fila'],r.sample.map(x=>[x.article_id+' / '+x.unit,stockNumber(x.previous_physical),stockNumber(x.physical),stockNumber(x.previous_reserved),stockNumber(x.reserved),stockNumber(x.previous_available),stockNumber(x.available),x.filename+' · '+x.source_row]));$('selected-inventory-notice').textContent=r.error_count?r.errors.map(e=>e.filename+' · fila '+e.row+' · '+(e.article_id||'SKU')+': '+e.message).join(' | '):'Revisa la comparación. Completa responsable, motivo y confirmación antes de utilizar estas existencias.';$('selected-inventory-commit').disabled=!r.ticket||!$('selected-inventory-ack').checked}catch(e){if(sequence===selectedInventorySequence)$('selected-inventory-notice').textContent=e.message}finally{selectedInventoryBusy=false;$('selected-inventory-preview').disabled=false}};
async function changeSelectedInventory(clear){if(selectedInventoryBusy||(!clear&&!selectedInventoryTicket))return;const dataset=$('dataset').value,sequence=selectedInventorySequence;selectedInventoryBusy=true;$('selected-inventory-commit').disabled=true;$('selected-inventory-clear').disabled=true;try{const r=await api(clear?'/api/inventory/clear':'/api/inventory/commit',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,context_fingerprint:state.documentary_context.fingerprint,ticket:selectedInventoryTicket,actor:$('selected-inventory-actor').value,reason:$('selected-inventory-reason').value,acknowledge_dated_reference:$('selected-inventory-ack').checked})});if(dataset!==$('dataset').value||sequence!==selectedInventorySequence)return;await refresh();$('selected-inventory-notice').textContent=clear?'Selección retirada. Se recuperan las referencias originales; las propuestas guardadas conservan su contenido.':r.status==='UNCHANGED'?'Estos inventarios ya estaban seleccionados. No se han duplicado.':'Existencias actualizadas para consulta en Stock y propuestas, con archivo y fila de origen. No se han creado facturas, movimientos de caja ni autorizaciones.'}catch(e){if(dataset===$('dataset').value)$('selected-inventory-notice').textContent=e.message}finally{selectedInventoryBusy=false;$('selected-inventory-commit').disabled=!selectedInventoryTicket||!$('selected-inventory-ack').checked;$('selected-inventory-clear').disabled=!state.selected_inventory||state.selected_inventory.status==='CLEARED'}}
$('selected-inventory-commit').onclick=()=>changeSelectedInventory(false);$('selected-inventory-clear').onclick=()=>changeSelectedInventory(true);
'''
